def kfs(ent,name,ed='classic'):
    v,a=clip(ent,name,ed); t=0; out=[]
    for i,k in enumerate(a['kf']):
        fr=v['frames'][k['f']] if k['f']<len(v['frames']) else None
        tr=[p-1000 for p in (fr or []) if p>1000]
        out.append(dict(i=i,t=t,d=k['d'],sc=k['sc'],tr=tr)); t+=k['d']
    return out
def seg(ent,name,start=0,ed='classic'):
    K=kfs(ent,name,ed); i=start; hits=[]; win=None; end=None; step=[]
    while i<len(K):
        k=K[i]
        for s in k['sc']:
            if s.startswith(('setatkgoto','setstrongonlygoto')) and win is None: win=k['t']
        h=[x for x in k['tr'] if x in HIT]
        if h: hits.append((k['t'],k['d'],h))
        term=[s for s in k['sc'] if s.startswith(('setanim','gotoframe'))]
        if term:
            end=(k['t'],term); break
        i+=1
    if end is None: end=(K[-1]['t']+K[-1]['d'],['eof'])
    t0=K[start]['t']
    return dict(start=t0,hits=hits,win=win,end=end,K=K)
def summ(ent,name,start=0,ed='classic'):
    s=seg(ent,name,start,ed); t0=s['start']
    if not s['hits']: return dict(clip=name,hits=0,total=(s['end'][0]-t0),end=s['end'][1],win=None if s['win'] is None else s['win']-t0)
    f=s['hits'][0][0]-t0; l=s['hits'][-1]; la=l[0]+l[1]-t0
    return dict(clip=name,hits=len(s['hits']),windup=f,active_end=la,total=s['end'][0]-t0,win=None if s['win'] is None else s['win']-t0,end=s['end'][1],trig=sorted({x for h in s['hits'] for x in h[2]}))
