NOT_DONE={'idle','run','fly','hover','land','stagger','hit'}
def walk(ent,name,depth=0):
    """follow chain: list of (clip, start_tick_global, kfs seen)"""
    K=kfs(ent,name); res=[]; i=0; t0=0; chain=[name]; seq=[]
    cur=name; glob=0; hops=0
    while True:
        K=kfs(ent,cur); end=None; nxt=None
        for k in K:
            seq.append((glob+k['t'],k['d'],cur,k['tr'],k['sc']))
            term=[s for s in k['sc'] if s.startswith(('setanim','gotoframe'))]
            if term:
                end=k['t']; nxt=term; break
        if end is None: end=K[-1]['t']+K[-1]['d']; nxt=['eof']
        glob+=end
        sa=[s.split()[1] for s in nxt if s.startswith('setanim')]
        if sa and sa[0] not in NOT_DONE and hops<2:
            try: kfs(ent,sa[0]); cur=sa[0]; hops+=1; chain.append(cur); continue
            except Exception: pass
        return chain,seq,glob,nxt
